// Wertet Button-Klicks (callback_data "wb:...") aus. Andere Callbacks (alte Menüs) werden ignoriert.
// Ausgang 1: HA-Aktion, Ausgang 2: Menü aktualisieren (nach kurzer Verzögerung),
// Ausgang 3: sofortige Rückmeldung als Telegram-Popup (answerCallbackQuery)
const data = String(msg.payload.content || '');
if (!data.startsWith('wb:')) return null;

const S = ((global.get('homeassistant') || {}).homeAssistant || {}).states || {};
const [, cmd, arg] = data.split(':');
const MODES = { 'automatik': 'Automatik', 'überschuss': 'Nur PV', 'günstigster_strom': 'Günstigster Strom', 'laden': 'Laden', 'stoppen': 'Stopp' };
const plugged = ['plugged', 'Plugged in'].includes((S['sensor.zoe_plug_state'] || {}).state);
let call = null;
let info = 'Aktualisiert';

if (cmd === 'm' && MODES[arg]) {
    call = { action: 'input_select.select_option', target: { entity_id: ['input_select.lade_modus'] }, data: { option: arg } };
    info = 'Modus: ' + MODES[arg] + (plugged ? '' : '\n(Auto nicht angesteckt – Wallbox wartet)');
} else if (cmd === 'o') {
    const on = (S['input_boolean.soc_override'] || {}).state === 'on';
    call = { action: 'input_boolean.toggle', target: { entity_id: ['input_boolean.soc_override'] }, data: {} };
    info = on ? 'SOC-Override AUS' : 'SOC-Override AN';
} else if (cmd === 't') {
    const cur = parseFloat((S['input_number.car_target_soc'] || {}).state) || 80;
    const value = Math.max(50, Math.min(80, cur + (parseFloat(arg) || 0)));
    if (value !== cur) call = { action: 'input_number.set_value', target: { entity_id: ['input_number.car_target_soc'] }, data: { value: value } };
    info = 'Ziel-SOC: ' + value + ' %' + (value === cur ? ' (Grenze 50–80 %)' : '');
}

if (call) node.status({ fill: 'blue', shape: 'dot', text: data + ' ' + new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin' }) });
const refresh = { wb: { chatId: msg.payload.chatId, messageId: msg.payload.messageId }, payload: {} };
const answer = { payload: { chatId: msg.payload.chatId, type: 'answerCallbackQuery', callbackQueryId: msg.payload.callbackQueryId, content: info, options: { show_alert: false } } };
return [call ? { payload: call } : null, refresh, answer];

// Baut Status-Text + Inline-Keyboard. Neue Nachricht (/wallbox) oder Bearbeiten der bestehenden (Button).
// v1.1: Emojis entfernt; aktiver Modus fett/groß im Text und als einziger markierter Button (▶ … ◀).
const S = ((global.get('homeassistant') || {}).homeAssistant || {}).states || {};
const st = id => (S[id] || {}).state;
const num = id => { const v = parseFloat(st(id)); return isNaN(v) ? null : v; };
const esc = s => String(s == null ? '–' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (v, d = 0) => v == null ? '–' : v.toLocaleString('de-DE', { minimumFractionDigits: d, maximumFractionDigits: d });

const MODES = {
    'automatik': 'Automatik',
    'überschuss': 'Nur PV',
    'günstigster_strom': 'Günstigster Strom',
    'laden': 'Laden',
    'stoppen': 'Stopp'
};
const mode = st('input_select.lade_modus');
const override = st('input_boolean.soc_override') === 'on';
const target = num('input_number.car_target_soc');
const cheap = st('binary_sensor.tibber_is_cheapest_now') === 'on';
const zeit = new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit' });

// Werte als ausgerichtete Tabelle (Monospace)
const rows = [
    ['Wallbox', st('sensor.easee_home_status') + ' · ' + fmt(num('sensor.wallbox_charge_power_kw'), 1) + ' kW · ' + fmt(num('sensor.easee_home_dynamic_charger_limit')) + ' A'],
    ['Zoe', fmt(num('sensor.zoe_battery')) + ' % → Ziel ' + fmt(target) + ' %'],
    ['Stecker', st('sensor.zoe_plug_state')],
    ['PV', fmt(num('sensor.calculated_pv_surplus')) + ' W Überschuss'],
    ['Speicher', fmt(num('sensor.rct_power_storage_battery_state_of_charge')) + ' %'],
    ['Strom', (st('sensor.tibber_cheapest_now') || '–') + (cheap ? ' · günstig' : ' · nicht günstig')],
    ['Kosten', fmt(num('sensor.wallbox_grid_cost_monthly'), 2) + ' € (Monat)'],
    ['Override', override ? 'AN – lädt über Ziel' : 'aus']
];
const table = rows.map(([k, v]) => k.padEnd(9) + esc(v)).join('\n');

const text = [
    '<b>Wallbox</b> · ' + zeit,
    '',
    'Modus: <b>' + esc((MODES[mode] || mode || '–').toUpperCase()) + '</b>',
    '<i>' + esc(st('sensor.smart_charging_status')) + '</i>',
    '',
    '<pre>' + table + '</pre>'
].join('\n');

const btn = m => ({ text: mode === m ? '▶ ' + MODES[m].toUpperCase() + ' ◀' : MODES[m], callback_data: 'wb:m:' + m });
const keyboard = [
    [btn('automatik'), btn('überschuss')],
    [btn('günstigster_strom')],
    [btn('laden'), btn('stoppen')],
    [{ text: override ? 'SOC-Override ausschalten' : 'SOC-Override einschalten', callback_data: 'wb:o' }],
    [{ text: 'Ziel −5 %', callback_data: 'wb:t:-5' }, { text: 'Ziel +5 %', callback_data: 'wb:t:5' }],
    [{ text: 'Aktualisieren', callback_data: 'wb:r' }]
];

const wb = msg.wb || { chatId: msg.payload.chatId };
if (wb.messageId) {
    msg.payload = {
        chatId: wb.chatId,
        type: 'editMessageText',
        content: text,
        options: { chat_id: wb.chatId, message_id: wb.messageId, parse_mode: 'HTML', reply_markup: { inline_keyboard: keyboard } }
    };
} else {
    msg.payload = {
        chatId: wb.chatId,
        type: 'message',
        content: text,
        options: { parse_mode: 'HTML', reply_markup: { inline_keyboard: keyboard } }
    };
}
return msg;
